mapper.update:
UPDATE hr_point_account
SET available_points = available_points - #{points},
    total_spent = total_spent + #{points},
    update_time = NOW()
WHERE id = #{accountId}
  AND tenant_id = #{tenantId}
  AND available_points >= #{points}
  AND deleted = 0

UPDATE hr_point_account
SET available_points = available_points - #{points},
    frozen_points = frozen_points + #{points},
    update_time = NOW()
WHERE id = #{accountId}
  AND tenant_id = #{tenantId}
  AND available_points >= #{points}
  AND deleted = 0

UPDATE hr_point_account
SET available_points = available_points + #{points},
    frozen_points = frozen_points - #{points},
    update_time = NOW()
WHERE id = #{accountId}
  AND tenant_id = #{tenantId}
  AND frozen_points >= #{points}
  AND deleted = 0
